// ─── Hero 右侧：Markdown 编辑器示意（纯 CSS，无外部图片依赖）───
function buildHeroVisual() {
  const panel = document.createElement('div');
  panel.className = 'jl-panel';
  panel.innerHTML = `
    <div class="jl-panel__bar">
      <span class="jl-dot"></span><span class="jl-dot"></span><span class="jl-dot"></span>
      <span class="jl-panel__file">2026-10-06.md</span>
    </div>
    <div class="jl-modes">
      <span class="jl-mode">分栏</span>
      <span class="jl-mode is-on">即时预览</span>
      <span class="jl-mode">仅编辑</span>
    </div>
    <pre class="jl-code"><code><span class="jl-h"># 今日</span>
笔记躺在<span class="jl-s">你自己的硬盘</span>上。
- [x] 写完这行任务
- [ ] 明天继续

[[知识网络]] #随手记 #日记</code></pre>
  `;
  return panel;
}

// ─── 三大承诺区块 ───
function renderPromises() {
  const section = document.createElement('section');
  section.className = 'promises section section--alt';
  section.innerHTML = `
    <div class="container">
      <h2 class="heading-lg" style="text-align:center; margin-bottom: var(--space-4);">
        三条底线，不接受商量
      </h2>
      <p class="text-muted" style="text-align:center; max-width:560px; margin:0 auto var(--space-12);">
        简录的设计前提很简单：这是你的笔记，不是我们的数据。
      </p>
      <div class="grid grid--3">
        ${PROMISES.map(
          (p) => `
            <div class="card promise-card">
              <div class="promise-card__icon">${p.icon}</div>
              <h3 class="heading-md" style="margin: var(--space-4) 0 var(--space-2);">${p.title}</h3>
              <p class="text-muted">${p.description}</p>
            </div>
          `
        ).join('')}
      </div>
    </div>
  `;
  return section;
}

// ─── 渲染页面 ───
function renderPage() {
  const root = document.getElementById('app');
  if (!root) return;

  // Navbar
  const navbar = new Navbar({
    brand: BRAND,
    links: NAV_LINKS,
    activeKey: 'jianlu',
  });
  root.appendChild(navbar.render());

  // Hero
  const hero = new Hero({
    title: APP_CONFIG.tagline,
    subtitle: APP_CONFIG.description,
    ctaText: `立即下载 v${VERSION}`,
    ctaLink: APP_CONFIG.downloadUrl,
    secondaryText: '查看核心能力',
    secondaryLink: '#writing',
  });
  const heroEl = hero.render();
  const visual = heroEl.querySelector('.hero__visual');
  if (visual) visual.appendChild(buildHeroVisual());
  root.appendChild(heroEl);

  // 三大承诺
  const promisesEl = renderPromises();
  promisesEl.id = 'promises';
  root.appendChild(promisesEl);

  // 写作
  const writing = new Features({ title: '写作：打开就能写', items: WRITING });
  const writingEl = writing.render();
  writingEl.id = 'writing';
  root.appendChild(writingEl);

  // 知识网络
  const knowledge = new Features({ title: '知识网络：笔记之间连成网', items: KNOWLEDGE });
  const knowledgeEl = knowledge.render();
  knowledgeEl.id = 'knowledge';
  root.appendChild(knowledgeEl);

  // 不怕丢
  const safety = new Features({ title: '不怕丢：数据在你手里', items: SAFETY });
  const safetyEl = safety.render();
  safetyEl.id = 'safety';
  root.appendChild(safetyEl);

  // Download CTA
  const download = new DownloadCTA({
    title: `立即下载简录 JianLu v${VERSION}`,
    subtitle: '不登录 · 不联网 · 不锁定你',
    platforms: PLATFORMS,
  });
  const downloadEl = download.render();
  downloadEl.id = 'download';

  // 全部版本 / 历史发布入口
  const releaseNote = document.createElement('p');
  releaseNote.className = 'release-note';
  releaseNote.innerHTML = `需要旧版本？前往
<a href="${RELEASE_URL}" target="_blank" rel="noopener noreferrer">全部发布版本</a>`;
  downloadEl.querySelector('.container').appendChild(releaseNote);
  root.appendChild(downloadEl);

  // Footer
  const footer = new Footer({
    copyright: COPYRIGHT,
    links: FOOTER_LINKS,
  });
  root.appendChild(footer.render());

  // 正文进入 DOM 后补一次锚点定位
  scrollToHash();
}

// DOM Ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', renderPage);
} else {
  renderPage();
}